import base64, json, os, traceback
try:
    import notebookutils  # Fabric runtime
except Exception:
    notebookutils = None

# The sealed contracts, embedded because Git sync does not copy data files into Files/.
# Payload = base64(json({relpath: base64(bytes)})).
_CONTRACTS_PAYLOAD = ""
FILES = "/lakehouse/default/Files"
try:
    # Needs a default Lakehouse attached; fail fast with a clear message if there isn't one.
    if not os.path.isdir(FILES):
        raise RuntimeError(
            "No default Lakehouse is attached to this notebook. Attach one and re-run: "
            "Explorer (left panel) -> Add data items -> your Lakehouse (e.g. the one this "
            "project targets) -> set as default. 00_setup writes the embedded contracts into "
            "its Files/_contracts."
        )
    _manifest = json.loads(base64.b64decode(_CONTRACTS_PAYLOAD).decode('utf-8'))
    _written = 0
    _only = str(globals().get('domain') or '').strip()
    for _rel, _b64 in sorted(_manifest.items()):
        if _only and not _rel.startswith(_only + '/'):
            continue
        _data = base64.b64decode(_b64)
        _fp = f"{FILES}/_contracts/{_rel}"
        try:
            # Write the exact bytes through the mount.
            os.makedirs(os.path.dirname(_fp), exist_ok=True)
            with open(_fp, "wb") as _f:
                _f.write(_data)
        except Exception:
            # Fallback: OneLake API (contracts are UTF-8 text).
            notebookutils.fs.put(f"Files/_contracts/{_rel}", _data.decode('utf-8'), True)
        _written += 1
    print(f"Materialised {_written} contract file(s) into Files/_contracts")
except Exception:
    tb = traceback.format_exc()
    print(tb)
    try:
        notebookutils.fs.put("Files/lakelogic_logs/setup_error.txt", tb, True)
    except Exception:
        pass
    raise

