# Create domain schemas, run-log tables and landing/log folders. Safe to re-run.
import os, traceback
try:
    import notebookutils  # Fabric runtime
except Exception:
    notebookutils = None

FILES = "/lakehouse/default/Files"


def _list_domains():
    """Domain dir names under Files/_contracts (notebookutils first, FUSE fallback)."""
    try:
        names = [f.name.rstrip("/") for f in notebookutils.fs.ls("Files/_contracts")
                 if getattr(f, 'isDir', False)]
        if names:
            return sorted(names)
    except Exception:
        pass
    try:
        base = f"{FILES}/_contracts"
        return sorted(d for d in os.listdir(base) if os.path.isdir(os.path.join(base, d)))
    except Exception:
        return []


def _sql(stmt):
    print(f"  -> {stmt}")
    spark.sql(stmt)  # noqa: F821 (Fabric global)


# `DomainRegistry` is not exported from the top-level `lakelogic` package.
from lakelogic.core.registry import DomainRegistry as _DomainRegistry


def _system_yamls():
    """Every `_system.yaml` under Files/_contracts, as driver-local paths.

    The registry is the authority on where a system's data lives. Walking the
    contracts tree here means setup provisions exactly what the contracts declare,
    rather than a convention that has to be kept in step with them by hand.
    """
    base = f"{FILES}/_contracts"
    found = []
    for root, _dirs, files in os.walk(base):
        if "_system.yaml" in files:
            found.append(os.path.join(root, "_system.yaml"))
    return sorted(found)


def _to_local(path):
    """A Spark-relative `Files/...` path as the driver-local mount path."""
    return f"{FILES}/{path[len('Files/'):]}" if path.startswith("Files/") else path


def _write_header_only_seeds(registry, to_local):
    """A header-only seed CSV for every contract whose rows come from `external_logic`.

    The date dimension reads a landing folder only so its source exists — LakeLogic
    refuses a missing one — and its generator replaces the rows. A folder that already
    holds a CSV is left alone: setup never overwrites landing data."""
    import csv
    written = []
    for rc in registry.get_active_contracts():
        cd = rc.contract_dict or {}
        path = str((cd.get("source") or {}).get("path") or "")
        if not cd.get("external_logic") or not path:
            continue
        folder = to_local(path)
        os.makedirs(folder, exist_ok=True)
        if any(f.endswith(".csv") for f in os.listdir(folder)):
            continue
        columns = [f["name"] for f in ((cd.get("model") or {}).get("fields") or [])]
        target = os.path.join(folder, "seed.csv")
        with open(target, "w", newline="", encoding="utf-8") as out:
            csv.writer(out).writerow(columns)
        written.append(target)
        print(f"  ok seed {target} ({len(columns)} columns)")
    return written


_RUN_LOG_COLS = (
    "(pipeline_run_id STRING, run_id STRING, timestamp STRING, engine STRING, "
    "contract STRING, contract_version STRING, stage STRING, dataset STRING, "
    "domain STRING, system STRING, environment STRING, data_layer STRING, "
    "status STRING, error_message STRING, counts_source BIGINT, counts_total BIGINT, "
    "counts_good BIGINT, counts_quarantined BIGINT, quarantine_ratio DOUBLE)"
)

try:
    domains = _list_domains()
    print(f"Domains discovered: {domains}")
    if not domains:
        raise RuntimeError(
            "No domains under Files/_contracts — the embedded contracts did not "
            "materialise (see the cell above) and the schema-enabled lakehouse must be "
            "attached as this notebook's default. Re-run 00_setup."
        )
    def _lakehouse_schema(root):
        parts = [p.strip().strip("`") for p in str(root or "").split(".")]
        return (parts[0], parts[1]) if len(parts) == 2 and all(parts) else None
    _per_domain_schemas, _per_domain_logs = [], []
    for _sy in _system_yamls():
        try:
            _st = _DomainRegistry.from_yaml(path=_sy, environment=environment, storage_mode="uc").storage
        except Exception as _exc:
            print(f"  ! could not read {_sy}: {_exc}")
            continue
        if not getattr(_st, "bronze_root", None):
            continue
        for _r in (_st.bronze_root, _st.silver_root, _st.gold_root, _st.domain_catalog, _st.quarantine_root):
            _ls = _lakehouse_schema(_r)
            if _ls:
                _per_domain_schemas.append(_ls)
        if _lakehouse_schema(_st.domain_catalog):
            _per_domain_logs.append(_lakehouse_schema(_st.domain_catalog))
    for _lh, _schema in dict.fromkeys(_per_domain_schemas):
        _sql(f"CREATE SCHEMA IF NOT EXISTS `{_lh}`.`{_schema}`")
    for _lh, _schema in dict.fromkeys(_per_domain_logs):
        _sql(f"CREATE TABLE IF NOT EXISTS `{_lh}`.`{_schema}`.lakelogic_run_log {_RUN_LOG_COLS} USING DELTA")
    for domain in ([] if _per_domain_schemas else domains):
        _sql(f"CREATE SCHEMA IF NOT EXISTS `{domain}`")
        _sql(f"CREATE TABLE IF NOT EXISTS `{domain}`.lakelogic_run_log {_RUN_LOG_COLS} USING DELTA")
    # Tables are created by the pipeline driver (`ddl_only`), so names match what it writes.
    # Landing folders come from each `_system.yaml` `storage.landing_root`.
    _subs = ["lakelogic_logs"]
    for _sy in _system_yamls():
        try:
            _reg = _DomainRegistry.from_yaml(
                path=_sy, environment=environment, storage_mode="uc",
            )
            _root = str(_reg.storage.landing_root or "").strip()
        except Exception as _exc:
            print(f"  ! could not read landing_root from {_sy}: {_exc}")
            continue
        if not _root:
            continue
        if "@onelake.dfs.fabric.microsoft.com/" in _root and ".Lakehouse/Files/" in _root:
            try:
                notebookutils.fs.mkdirs(_root)
                print(f"  ok {_root}")
            except Exception as _exc:
                print(f"  ! could not create {_root}: {_exc}")
            _write_header_only_seeds(_reg, _to_local)
            continue
        # Remote storage (a shortcut's target, or abfss://) belongs to the source system:
        # setup never creates folders in it.
        if globals().get("_landing_spec") and (not _root.startswith("Files/") or (
                globals().get("_shortcut_root")
                and _root.startswith(globals()["_shortcut_root"] + "/"))):
            print(f"  - remote landing, not created: {_root}")
            _write_header_only_seeds(_reg, _to_local)
            continue
        # mkdirs adds the `Files/` prefix itself.
        _subs.append(_root[len("Files/"):] if _root.startswith("Files/") else _root)
        _write_header_only_seeds(_reg, _to_local)
    for sub in dict.fromkeys(_subs):
        try:
            notebookutils.fs.mkdirs(f"Files/{sub}")
        except Exception:
            os.makedirs(f"{FILES}/{sub}", exist_ok=True)
        print(f"  ok Files/{sub}")
    print("=" * 60)
    print(f"  Provisioned schemas: {', '.join(domains)}")
    print("=" * 60)
except Exception:
    tb = traceback.format_exc()
    print(tb)
    try:
        notebookutils.fs.put("Files/lakelogic_logs/setup_error.txt", tb, True)
    except Exception:
        pass
    raise

